var AUDIT={settimana:'13 – 17 agosto 2026',visti:21,scartati:'oltre 90 risultati scorsi nelle ricerche',nonverificate:['Swissmedic (avvisi dispositivi)','openFDA','Retraction Watch (archivio salvati vuoto)','pagine ESSKA · AAOS · ICRS','registri protesici (SIRIS · RIPO · NJR · AOANJRR)'],nota:'Recupero straordinario del 17 agosto: i briefing dal 13 al 16 non sono partiti (il compito automatico pubblicava a vuoto: push bloccato, corretto oggi). La finestra di ricerca copre i giorni persi: 21 lavori riaperti per esteso su PubMed, 10 tenuti. Nessuna scheda contraddice oggi una tua tecnica: 0 arancioni è un conteggio, non una rassicurazione.'};
var TENSIONS=[{id:"1",t:"Il rinforzo laterale (LET) su innesto rigido",fai:"Fai il LET su tutti i pazienti che ricostruisci, con innesto di retto femorale.",prove:"Il beneficio del LET è dimostrato su innesto hamstring. Il protocollo STABILITY 2 scrive testualmente che nessuno studio ha stabilito se quel beneficio resta con innesti più rigidi. Aggiornamento del 12 agosto: un database americano su 5.944 gesti combinati conferma che il tempo unico è sicuro — ma non distingue né il costrutto né l'innesto. Nuovo il 17 agosto: il trial GRASE (Copenaghen, 150 pazienti, reclutamento completo) confronterà i tre innesti, quadricipitale compreso — ma senza LET: risponderà sull'innesto, non sulla tua combinazione.",fare:"Non cambiare nulla: non è un errore, è una lacuna della letteratura. Ma se un collega ti chiede perché lo fai su tutti, la risposta onesta è: «beneficio dimostrato su hamstring, esteso per ragionevolezza al quadricipitale».",chiude:"STABILITY 2, braccio quadricipitale con e senza LET, 1292 pazienti. Risultati attesi nel 2029."},{id:"2",t:"Il tuo costrutto non è quello studiato",fai:"Lemaire modificato, fissazione onlay, passaggio superficiale al collaterale laterale.",prove:"I trial usano il passaggio profondo sotto il collaterale e la fissazione con graffa. Sono due costrutti biomeccanicamente diversi, che la letteratura tratta come se fossero la stessa cosa.",fare:"Quando leggi i risultati di un trial sul LET, ricorda che non sono automaticamente i tuoi. Segnale a tuo favore: le note tecniche recenti si stanno spostando verso l'onlay — il campo va dove sei tu, le prove non ancora.",chiude:"Un confronto diretto fra i due costrutti. Oggi non esiste, e nemmeno STABILITY 2 lo risolverà."},{id:"3",t:"Nella radice meniscale conta l'estrusione, non il ritardo",fai:"Rifissazione della radice con tecnica transtibiale. Nel colloquio si tende a pesare il grado condrale e il tempo trascorso dall'infortunio.",prove:"All'analisi multivariata il ritardo NON è predittore indipendente di progressione (p=0,31). Lo sono l'estrusione meniscale (p=0,023) e la larghezza dello spazio articolare preoperatoria. La storia naturale (64 radici non operate, 12 agosto): estrusione da 3,1 a 4,3 mm in 6 mesi mentre il dolore migliora; converte a chirurgia chi ha più varo (soglia HKA 5,5°). E l'osteoporosi più che raddoppia il rischio di frattura subcondrale nella donna (OR 2,29). Lo stato dell'arte J ISAKOS del 17 agosto (Pittsburgh, con Seil, Getgood e Karlsson) conferma la transtibiale come tecnica di scelta e aggiunge il dato che pesa: nel trial sulla centralizzazione l'estrusione aumenta a 6 mesi nel 96,2% delle ginocchia, qualunque cosa si faccia.",fare:"AZIONE CONCRETA, da subito: misura e referta l'estrusione sulla risonanza preoperatoria, e usa quella nel colloquio sul rischio di progressione, al posto del grado condrale e del tempo trascorso. Aggiungi l'asse (varo oltre ~5,5°) e, nella donna, la densità ossea: sono gli altri volti del carico basale.",chiude:"Studi prospettici con l'estrusione come variabile principale. Confidenza attuale: media — due retrospettivi piccoli e ora una coorte prospettica (64 pazienti) nella stessa direzione."},{id:"4",t:"Il criterio di rientro non regge sul tuo innesto",fai:"Se usi la simmetria di forza al 90% come criterio per il ritorno allo sport.",prove:"Sul retto femorale, a 6 mesi, il deficit di estensione è del 29% (simmetria 71%), mentre la flessione recupera al 93%. Con una soglia del 90% quasi nessuno passa a 6 mesi.",fare:"Verifica che cosa misuri davvero a 6 mesi. Sul quadricipitale aspettati tempi più lunghi per l'estensione: o sposti la scadenza, o cambi la misura. Dato su 31 pazienti, soli maschi, un solo centro.",chiude:"Studi che leghino il deficit di forza a esiti duri (rirottura, mancato rientro) e non a misure intermedie."},{id:"5",t:"Nel minced cartilage varia il tessuto, non solo la tecnica",fai:"Trapianto di cartilagine tritata con filiera dedicata.",prove:"I campioni prelevati da difetti debridati variano oltre dieci volte in peso umido, DNA totale e proteoglicani. Dipende da quale tessuto si raccoglie, non dallo strumento.",fare:"Se un caso va peggio di un altro a parità di gesto chirurgico, la variabile può essere la qualità del tessuto raccolto. Utile saperlo prima di attribuirlo alla tecnica.",chiude:"Una caratterizzazione di vitalità e resa cellulare specifica della filiera che usi. Oggi non esiste."}];
var MUTE={5:"Revisione tecnica senza stima aggregata: l'intervallo 0–56,5% riflette definizioni disomogenee fra studi, non un rischio misurato — non può né affermare né escludere un tasso reale di complicanze.",10:"Protocollo di trial: nessun risultato per costruzione. Registrato perché è uno dei pochi RCT con braccio quadricipitale dedicato e il reclutamento è completo."};
